(function(){
  var t = scope.type_idx;
  var a, b, expr, ans, step1;
  if (t === 0) {
    a = scope.a_val;
    b = scope.b_val;
    expr = a + ' + (-' + b + ')';
    ans = (a - b).toString();
    step1 = a + ' - ' + b + ' = ' + ans;
  } else if (t === 1) {
    a = scope.a_val;
    b = Math.round((scope.b_val + 0.5) * 10) / 10;
    expr = a + ' - (-' + b + ')';
    ans = (Math.round((a + b) * 10) / 10).toString();
    step1 = a + ' + ' + b + ' = ' + ans;
  } else if (t === 2) {
    a = Math.round((scope.a_val + 0.2) * 10) / 10;
    b = Math.round((scope.b_val + 0.7) * 10) / 10;
    expr = '-' + a + ' + ' + b;
    ans = (Math.round((-a + b) * 10) / 10).toString();
    step1 = '-' + a + ' + ' + b + ' = ' + ans;
  } else {
    a = scope.a_val;
    b = scope.b_val;
    expr = '-' + a + ' - (-' + b + ')';
    ans = (-a + b).toString();
    step1 = '-' + a + ' + ' + b + ' = ' + ans;
  }
  return { expr: expr, ans: ans, step1: step1 };
})()

(function(){
  var t = scope.op_idx;
  var a = scope.a_val, b = scope.b_val;
  var expr, ans, rule;
  if (t === 0) {
    expr = a + ' \\times (-' + b + ')';
    ans = (a * (-b)).toString();
    rule = '\\text{Positive} \\times \\text{Negative} = \\text{Negative}';
  } else if (t === 1) {
    expr = '(-' + a + ') \\times (-' + b + ')';
    ans = ((-a) * (-b)).toString();
    rule = '\\text{Negative} \\times \\text{Negative} = \\text{Positive}';
  } else if (t === 2) {
    var prod = a * b;
    expr = prod + ' \\div (-' + b + ')';
    ans = (-a).toString();
    rule = '\\text{Positive} \\div \\text{Negative} = \\text{Negative}';
  } else {
    var prod = a * b;
    expr = '(-' + prod + ') \\div (-' + b + ')';
    ans = a.toString();
    rule = '\\text{Negative} \\div \\text{Negative} = \\text{Positive}';
  }
  return { expr: expr, ans: ans, rule: rule };
})()

(function(){
  var p = scope.pattern_idx;
  var a = scope.a, b = scope.b, c = scope.c;
  var expr, ans, step1, step2;
  if (p === 0) {
    var prod = b * (-c);
    expr = a + ' + ' + b + ' \\times (-' + c + ')';
    ans = (a + prod).toString();
    step1 = b + ' \\times (-' + c + ') = ' + prod;
    step2 = a + ' + (' + prod + ') = ' + ans;
  } else if (p === 1) {
    var prod = b * (-c);
    expr = a + ' - ' + b + ' \\times (-' + c + ')';
    ans = (a - prod).toString();
    step1 = b + ' \\times (-' + c + ') = ' + prod;
    step2 = a + ' - (' + prod + ') = ' + ans;
  } else if (p === 2) {
    var m = b * c;
    var quot = -b;
    expr = a + ' + ' + m + ' \\div (-' + c + ')';
    ans = (a + quot).toString();
    step1 = m + ' \\div (-' + c + ') = ' + quot;
    step2 = a + ' + (' + quot + ') = ' + ans;
  } else {
    var m = b * c;
    var quot = b;
    expr = a + ' - (-' + m + ') \\div (-' + c + ')';
    ans = (a - quot).toString();
    step1 = '(-' + m + ') \\div (-' + c + ') = ' + quot;
    step2 = a + ' - ' + quot + ' = ' + ans;
  }
  return { expr: expr, ans: ans, step1: step1, step2: step2 };
})()

(function(){
  var p = scope.p_idx;
  var a = scope.a, b = scope.b, c = scope.c;
  var expr, ans, step1, step2;
  if (p === 0) {
    var prod1 = (-a) * (-b);
    var prod2 = c * (-2);
    expr = '(-' + a + ') \\times (-' + b + ') + ' + c + ' \\times (-2)';
    ans = (prod1 + prod2).toString();
    step1 = '(-' + a + ') \\times (-' + b + ') = ' + prod1 + ' \\text{ and } ' + c + ' \\times (-2) = ' + prod2;
    step2 = prod1 + ' + (' + prod2 + ') = ' + ans;
  } else if (p === 1) {
    var bracket = -a + b;
    expr = '(-' + a + ' + ' + b + ') \\times (-' + c + ')';
    ans = (bracket * (-c)).toString();
    step1 = '(-' + a + ' + ' + b + ') = ' + bracket;
    step2 = bracket + ' \\times (-' + c + ') = ' + ans;
  } else {
    var sum = a + b;
    var mult = sum * c;
    expr = '(-' + mult + ') \\div (-' + a + ' - ' + b + ')';
    var bracket = -a - b;
    ans = c.toString();
    step1 = '(-' + a + ' - ' + b + ') = ' + bracket;
    step2 = '(-' + mult + ') \\div (' + bracket + ') = ' + ans;
  }
  return { expr: expr, ans: ans, step1: step1, step2: step2 };
})()
